from __future__ import annotations

def is_balanced(s: str) -> bool:
    """
    >>> is_balanced("({[]})")
    True
    >>> is_balanced("({[})")
    False
    """
    stack: list[str] = []
    bracket_map: dict[str, str] = {"(": ")", "[": "]", "{": "}"}
    for c in s:
        if c in bracket_map:
            stack.append(c)
        elif c in bracket_map.values():
            if not stack or bracket_map[stack.pop()]!= c:
                return False
    return not stack

